/**
 * A newtype wrapper for strings that contain sensitive data (secrets, tokens,
 * passwords).
 *
 * # Security properties
 *
 * - **`Debug`** and **`Display`** implementations redact the value, preventing
 * accidental exposure in logs, error chains, and tracing output.
 * - **`ZeroizeOnDrop`** overwrites the backing heap allocation with zeros when
 * the value is dropped.
 * - **`Serialize`** is **transparent** (`#[serde(transparent)]`): serializing a
 * `SecretString` emits the plaintext value. Never serialize structs containing
 * `SecretString` to logs or debug output — use `Debug` formatting instead.
 * - **`Clone`** creates a new heap allocation containing the secret. Each clone
 * must be properly dropped (not leaked or stored in a non-zeroizing container)
 * to ensure the zeroize guarantee is upheld.
 * - **`PartialEq`** uses the standard `String` comparison, which short-circuits
 * on the first mismatched byte. Do not use `PartialEq` for authentication
 * comparisons where timing side channels are a concern; use a constant-time
 * comparison function instead (e.g., `subtle::ConstantTimeEq` or
 * `argon2::password_hash::PasswordVerifier`).
 */
export type SecretString = string;

/**
 * Resource selector on a grant: which hosts / software items a
 * selector-capable action may target. `All` is the M1 default; write-path
 * acceptance of the narrowing variants lands in M2 (grant validation, not
 * this type).
 *
 * Serialized form is the `access_grants.selector` storage JSON
 * (`06-grant-model.md` §Storage schema): `{"type":"all"}`,
 * `{"type":"tags","ids":[…]}`, … — uniform `ids` field. Unknown extra
 * keys are ignored on deserialize (serde internally-tagged enums cannot
 * `deny_unknown_fields`); that is safe because an ignored key can never
 * broaden authority and a missing/mistyped `ids` still fails as a
 * missing field.
 */
export type Selector = {
    type: 'all';
} | {
    ids: Array<string>;
    type: 'tags';
} | {
    ids: Array<string>;
    type: 'hosts';
} | {
    ids: Array<string>;
    type: 'software';
} | {
    ids: Array<string>;
    type: 'items';
};

/**
 * Selector-capability level of an action — first-class catalog metadata
 * (`05-action-model.md` §Selector-capable actions). Each level admits
 * the previous levels' selector kinds.
 */
export const SelectorSupport = {
    NONE: 'none',
    HOST: 'host',
    HOST_AND_SOFTWARE: 'host_and_software'
} as const;

/**
 * Selector-capability level of an action — first-class catalog metadata
 * (`05-action-model.md` §Selector-capable actions). Each level admits
 * the previous levels' selector kinds.
 */
export type SelectorSupport = typeof SelectorSupport[keyof typeof SelectorSupport];

